-- SELECT only. Run after apply. 예/아니오 항목은 모두 예, 그 밖의 값은 precheck의 같은 이름 항목과 같은 값이어야 한다.
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261028030000' and name='tg_room_day_context')=1 then '예' else '아니오' end as value
union all select 'context function: definer, empty search_path, no anon or PUBLIC execute',case when exists(select 1 from pg_proc p where p.oid=to_regprocedure('public.app_feed_room_day_context(uuid,text,date)') and p.prosecdef and p.proconfig=array['search_path=""'] and not has_function_privilege('anon',p.oid,'execute') and coalesce(p.proacl::text,'')!~'(^|[{,])=') then '예' else '아니오' end
union all select 'context function: service_role only',case when has_function_privilege('service_role','public.app_feed_room_day_context(uuid,text,date)','execute') and not has_function_privilege('authenticated','public.app_feed_room_day_context(uuid,text,date)','execute') and not has_function_privilege('anon','public.app_feed_room_day_context(uuid,text,date)','execute') then '예' else '아니오' end
union all select 'feed items: service_role still cannot read title or summary',case when not has_column_privilege('service_role','public.app_feed_items','title','select') and not has_column_privilege('service_role','public.app_feed_items','summary','select') and not has_any_column_privilege('anon','public.app_feed_items','select') then '예' else '아니오' end
union all select 'feed items rows',(select count(*)::text from public.app_feed_items)
union all select 'feed items grants policies hash',md5(coalesce((select string_agg(c.relname||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid=to_regclass('public.app_feed_items')),'')
  ||coalesce((select string_agg(p.polname::text||p.polcmd::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),''),',' order by p.polname) from pg_policy p where p.polrelid=to_regclass('public.app_feed_items')),''));
